# extensions for an extensionless command the way cmd.exe/PowerShell do, and the
# Claude Code CLI on this machine isn't on PATH at all (it lives under the
# Roaming\Claude app data dir, no registered App Execution Alias). shutil.which()
# handles the PATHEXT case; these extra search dirs cover the not-on-PATH case.
# Evaluated on every call (not at import) so a reinstall or app update that moves
# the CLI is picked up, and ~/.local/bin covers Claude Code's native installer.
def extra_search_dirs():
    dirs = [str(Path.home() / ".local" / "bin")]
    appdata = os.environ.get("APPDATA")
    if appdata:
        dirs += [str(p) for p in (Path(appdata) / "Claude" / "claude-code").glob("*") if p.is_dir()]
    return dirs


def resolve_executable(name):
    found = shutil.which(name)
    if found:
        return found
    for extra_dir in extra_search_dirs():
        candidate = shutil.which(name, path=extra_dir)
        if candidate:
            return candidate
    return None

