def decider_lock_path(checkout):
    """The vote lock's file for `checkout` (its git dir's mob-decider.lock), or None when it is not a git checkout."""
    try:
        done = _git(checkout, "rev-parse", "--git-path", DECIDER_LOCK, check=False)
